/****************************************************************************
 * Name: rk3576_cif_stop
 ****************************************************************************/

int rk3576_cif_stop(int host)
{
  uint32_t off;

  if (host < 0 || host > 4)
    {
      return -EINVAL;
    }

  off = cif_csi_offset(host);
  cif_putreg(off + CIF_MIPI_ID0_CTRL0, 0);
  cif_putreg(off + CIF_MIPI_INTEN, 0);
  return OK;
}

