/* 通道基址。TRM Part1 14.4.1 内部地址映射。 */

#define TIMER_CH_BASE(n)      (0x2acc0000ul + (uintptr_t)(n) * 0x1000)

#define TIMER_CH_ALARM        0        /* 闹钟：它的中断号设备树里有   */
#define TIMER_CH_COUNTER      1        /* 计数：自由运行，不用中断     */

