      if (gain[i] < AWB_GAIN_MIN)
        {
          gain[i] = AWB_GAIN_MIN;
        }
      else if (gain[i] > AWB_GAIN_MAX)
        {
          gain[i] = AWB_GAIN_MAX;
        }
    }

  ninfo("AWB 增益 R/G/B = %d/%d/%d (x256)\\n", gain[0], gain[1], gain[2]);
}

''' + anchor2)

