  rk3576_pinmux_set(UART4_PIN_BANK, UART4_PIN_RTS, 0);
  rk3576_gpio_setdir(UART4_PIN_BANK, UART4_PIN_RTS, true);
  rk3576_gpio_write(UART4_PIN_BANK, UART4_PIN_RTS, false);

