  rk3576_pinmux_set(BT_RST_BANK, BT_RST_PIN, 0);
  rk3576_gpio_setdir(BT_RST_BANK, BT_RST_PIN, true);
  rk3576_gpio_write(BT_RST_BANK, BT_RST_PIN, false);
