     *     控制器在总线空闲时停掉时钟，而 SDIO 卡靠持续时钟应答与报中断。
     *     原厂对 SDIO 也是特意不置这一位的。
     */

    dw_putreg(base, DWMMC_CLKENA, 0);
    dw_update_clk(base);
    dw_putreg(base, DWMMC_CLKSRC, 0);
    dw_update_clk(base);
    dw_putreg(base, DWMMC_CLKDIV, hw->is_sdio ? 0 : 30);
    dw_update_clk(base);
    dw_putreg(base, DWMMC_CLKENA, DWMMC_CLKENA_ENABLE);
    dw_update_clk(base);
    up_mdelay(2);''', 1)
